function toSnakeCase(text) {
    return text.replace(/([a-z0-9]|(?=[A-Z]))([A-Z])/g, '$1_$2').toLowerCase().replace(/[-\s]+/g, '_');
}
const src_toSnakeCase = toSnakeCase;
function getMeta(name, value) {
    return {
        [name]: {
            property: name,
            content: value
        }
    };
}
const pluginOpenGraph = (pluginOptions)=>({
        name: 'rsbuild-plugin-open-graph',
        setup (api) {
            api.modifyRsbuildConfig((userConfig, { mergeRsbuildConfig })=>{
                const BASIC_KEYS = [
                    'url',
                    'type',
                    'title',
                    'siteName',
                    'image',
                    'audio',
                    'video',
                    'locale',
                    'determiner',
                    "description"
                ];
                const getMetaByOptions = (options)=>{
                    const meta = {};
                    BASIC_KEYS.forEach((key)=>{
                        const val = options[key];
                        if (void 0 !== val) {
                            const name = `og:${src_toSnakeCase(key)}`;
                            Object.assign(meta, getMeta(name, val));
                        }
                    });
                    if (options.twitter) Object.entries(options.twitter).forEach(([key, val])=>{
                        Object.assign(meta, getMeta(`twitter:${key}`, val));
                    });
                    return meta;
                };
                const extraConfig = 'function' == typeof pluginOptions ? {
                    html: {
                        meta: ({ entryName })=>getMetaByOptions(pluginOptions({
                                entryName
                            }))
                    }
                } : {
                    html: {
                        meta: getMetaByOptions(pluginOptions)
                    }
                };
                return mergeRsbuildConfig(extraConfig, userConfig);
            });
        }
    });
export { pluginOpenGraph };
